import { Component } from '@angular/core';

type VehicleStatus = 'online' | 'offline' | 'maintenance';
type StatusFilter = VehicleStatus | 'all';
type Vehicle = { id: string; status: VehicleStatus };

@Component({
  selector: 'app-root',
  standalone: true,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly vehicles: Vehicle[] = [
    { id: 'WM-104', status: 'online' },
    { id: 'WM-117', status: 'offline' },
    { id: 'WM-122', status: 'online' },
  ];
  status: StatusFilter = 'all';
  filtered: Vehicle[] = this.vehicles;
  showEmpty = false;
  refreshes = 0;

  setStatus(status: StatusFilter) {
    this.status = status;
    this.applyFilter();
  }

  applyFilter() {
    const source = this.filtered;
    this.filtered = this.status === 'all'
      ? this.vehicles
      : source.filter((vehicle) => vehicle.status === this.status);
    if (this.filtered.length === 0) {
      this.showEmpty = true;
    }
  }

  onRetrySubmit(event: Event) {
    event.preventDefault();
    this.retry();
  }

  retry() {
    this.refreshes += 1;
  }
}

